assignments.value:
Voce e o motor de interpretacao de um assistente de tarefas e agenda usado via WhatsApp. Sua unica saida deve ser um JSON valido, sem markdown, sem texto fora do JSON. O fuso do usuario e America/Sao_Paulo (UTC-3). Toda data que voce devolver deve estar em UTC terminando em Z (ex: 2026-08-30T13:00:00.000Z) - some 3 horas ao converter horario local para UTC. Voce vai receber a data/hora atual em UTC para usar como referencia de 'hoje', 'amanha' etc.

Escolha exatamente um dos formatos abaixo:

1) Criar tarefa:
{"intent":"create_task","payload":{"title":string,"description":string ou null,"dueAt":string ISO8601 em UTC ou null,"priority":numero de 1 a 5 (1 = mais urgente, use 3 se nao disser),"originalMessage":string com a mensagem original}}

2) Criar evento:
{"intent":"create_event","payload":{"title":string,"startsAt":ISO8601 UTC,"endsAt":ISO8601 UTC,"location":string ou null,"originalMessage":string}}

3) Concluir tarefa(s) por numero (o usuario cita o numero da tarefa, ex '#12' ou 'tarefa 12'):
{"intent":"complete_task","task_numbers":[numero,...]}

4) Listar/consultar itens de um periodo:
{"intent":"list_items","filters":{"type":"all" ou "task" ou "event","status":string ou null,"priority":numero ou null,"period":"hoje" ou "amanha" ou "essa_semana" ou "proximos_7_dias" ou "esse_mes" ou "personalizado","period_start":ISO8601 UTC (preencha SO se period for \"personalizado\", senao deixe null),"period_end":ISO8601 UTC (preencha SO se period for \"personalizado\", senao deixe null),"q":string ou null}}
Prefira sempre um dos labels prontos (hoje/amanha/essa_semana/proximos_7_dias/esse_mes) em vez de calcular datas na mao - o calculo exato e feito por codigo depois, voce so escolhe o label certo pelo que o usuario pediu. So use \"personalizado\" com period_start/period_end quando o usuario der um intervalo especifico (ex: 'entre 10/09 e 20/09').

5) Quando nao entender a mensagem ou a acao pedida nao estiver na lista acima (ex: reagendar, cancelar, mudar politica de aviso, pedir resumo do dia - ainda nao implementados):
{"intent":"unknown","reason":"frase curta explicando o que faltou entender ou por que ainda nao da pra fazer isso"}

Regras gerais: nunca invente um intent fora da lista. Se faltar informacao essencial (ex: titulo da tarefa), use intent unknown pedindo o que falta. Responda apenas com o JSON, nada mais.

parameters.jsCode:
const entrada = $('Normalizar entrada').item.json;
const raw = $json.choices?.[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { intent: 'unknown', reason: 'Nao consegui entender essa mensagem, pode reformular?' };
}

const supportedIntents = ['create_task', 'create_event', 'complete_task', 'list_items'];
const supported = supportedIntents.includes(parsed.intent);

// Resolve labels de periodo (hoje/amanha/essa_semana/proximos_7_dias/esse_mes) em codigo
// deterministico, em vez de pedir pra IA calcular data exata - mais barato (menos coisa
// pra IA acertar) e mais confiavel (sem risco de conta de fuso horario errada).
// America/Sao_Paulo nao tem mais horario de verao, entao UTC-3 fixo e seguro.
function resolvePeriodo(label, agoraUtcIso, customStart, customEnd) {
  const OFFSET_MS = 3 * 60 * 60 * 1000;
  const agoraLocal = new Date(new Date(agoraUtcIso).getTime() - OFFSET_MS);

  function localMidnight(addDays) {
    return new Date(Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth(), agoraLocal.getUTCDate() + addDays, 0, 0, 0, 0));
  }
  function toUtcIso(localDate) {
    return new Date(localDate.getTime() + OFFSET_MS).toISOString();
  }

  if (label === 'personalizado' && customStart && customEnd) {
    return { period_start: customStart, period_end: customEnd };
  }

  let start, end;
  if (label === 'hoje') {
    start = localMidnight(0);
    end = localMidnight(1);
  } else if (label === 'amanha') {
    start = localMidnight(1);
    end = localMidnight(2);
  } else if (label === 'essa_semana') {
    const dow = agoraLocal.getUTCDay();
    start = localMidnight(-dow);
    end = localMidnight(7 - dow);
  } else if (label === 'esse_mes') {
    start = new Date(Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth(), 1, 0, 0, 0, 0));
    end = new Date(Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth() + 1, 1, 0, 0, 0, 0));
  } else {
    // proximos_7_dias e qualquer label desconhecido caem aqui como padrao seguro
    start = localMidnight(0);
    end = localMidnight(7);
  }

  return { period_start: toUtcIso(start), period_end: toUtcIso(end) };
}

let commandBody = null;
if (parsed.intent === 'create_task') commandBody = { intent: 'create_task', payload: { ...parsed.payload, source: 'n8n' } };
if (parsed.intent === 'create_event') commandBody = { intent: 'create_event', payload: { ...parsed.payload, source: 'n8n' } };
if (parsed.intent === 'complete_task') commandBody = { intent: 'complete_task', task_numbers: parsed.task_numbers };
if (parsed.intent === 'list_items') {
  const f = parsed.filters || {};
  const periodo = resolvePeriodo(f.period, entrada.agoraUtc, f.period_start, f.period_end);
  commandBody = {
    intent: 'list_items',
    filters: {
      type: f.type || 'all',
      status: f.status || undefined,
      priority: f.priority || undefined,
      period_start: periodo.period_start,
      period_end: periodo.period_end,
      q: f.q || undefined
    }
  };
}

return {
  json: {
    ...entrada,
    intent: parsed.intent,
    reason: parsed.reason || null,
    commandBody,
    supported: supported ? 'yes' : 'no'
  }
};

const entrada = $('Normalizar entrada').item.json;
const api = $json;

function formatDateBr(iso) {
  if (!iso) return null;
  try {
    return new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
  } catch (e) {
    return iso;
  }
}

function respostaSimples(reply) {
  return { json: { telefone: entrada.telefone, userExternalId: entrada.userExternalId, reply, precisaIA: 'no' } };
}

// Resposta simples e deterministica (sem custo de IA) pra tudo que da pra descrever
// direto a partir do JSON da API. So listas longas caem numa chamada de IA depois.
if (!api.ok) {
  const msg = api.errors?.[0]?.message || 'nao consegui completar essa acao agora';
  return respostaSimples(`Deu ruim aqui: ${msg}. Pode tentar de novo?`);
}

if (api.intent === 'create_task') {
  const t = api.data.task;
  const prazo = formatDateBr(t.dueAt);
  return respostaSimples(`Tarefa #${t.number} criada: "${t.title}"${prazo ? ` (prazo ${prazo})` : ''}.`);
}

if (api.intent === 'create_event') {
  const e = api.data.event;
  return respostaSimples(`Evento criado: "${e.title}", de ${formatDateBr(e.startsAt)} ate ${formatDateBr(e.endsAt)}.`);
}

if (api.intent === 'complete_task') {
  const completed = api.data.completed || [];
  const notFound = api.data.notFound || [];
  const partes = [];
  if (completed.length) partes.push(`Concluida${completed.length > 1 ? 's' : ''}: ${completed.map((t) => '#' + t.number).join(', ')}.`);
  if (notFound.length) partes.push(`Nao achei: ${notFound.map((n) => '#' + n).join(', ')}.`);
  return respostaSimples(partes.join(' ') || 'Nada pra concluir.');
}

if (api.intent === 'list_items') {
  const items = api.data.items || [];
  if (items.length === 0) {
    return respostaSimples('Nada encontrado nesse periodo.');
  }
  if (items.length <= 3) {
    const linhas = items.map((item) => item.itemType === 'task'
      ? `#${item.number} ${item.title} (${formatDateBr(item.dueAt) || 'sem prazo'})`
      : `${item.title} (${formatDateBr(item.startsAt)})`);
    return respostaSimples(linhas.join('\n'));
  }
  // Lista longa: vale gastar 1 chamada de IA pra resumir de forma legivel.
  return { json: { ...entrada, apiResultado: JSON.stringify(api), precisaIA: 'yes' } };
}

return respostaSimples('Feito.');

const entrada = $('Preparar resposta').item.json;
const raw = $json.choices?.[0]?.message?.content || 'Encontrei varios itens nesse periodo, mas nao consegui resumir agora.';

return {
  json: {
    telefone: entrada.telefone,
    userExternalId: entrada.userExternalId,
    reply: raw.trim()
  }
};
